import { build } from "esbuild";
import { writeFile } from "node:fs/promises";

const result = await build({
  entryPoints: ["lib/smart-apply-core/src/native-entry.ts"],
  bundle: true, write: false, format: "iife", platform: "browser", target: "es2020",
  minify: true, legalComments: "none",
});
const code = result.outputFiles[0].text;
if (/\bchrome\.(?:runtime|storage|tabs)\b/.test(code)) throw new Error("Chrome API in mobile runtime");
await writeFile("lib/smart-apply-core/src/native-script.ts",
  "// Generated by scripts/build-smart-apply-native.mjs from shared original ATS algorithms.\n"
  + "export const nativeSmartApplyScript = " + JSON.stringify(code) + ";\n");
console.info(`Native Smart Apply runtime built (${code.length} characters); no Chrome APIs.`);
